// Generates each platform's design tokens from payments/design/tokens.json and its icons from
// payments/design/icons.json (docs/06 §8): Kotlin for the Android app, Swift for the iOS app,
// CSS custom properties and an icon module for the web console. `node gen-tokens.mjs` writes
// them; `node gen-tokens.mjs --check` exits 1 when a generated file is out of date (npm run
// check runs it).
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(join(root, 'design', 'tokens.json'), 'utf8'));
const iconSet = JSON.parse(readFileSync(join(root, 'design', 'icons.json'), 'utf8'));
const header = 'Generated by payments/tools/gen-tokens.mjs from payments/design/tokens.json. Do not edit: change the tokens and run `npm run tokens`.';
const iconHeader = 'Generated by payments/tools/gen-tokens.mjs from payments/design/icons.json. Do not edit: change the icons and run `npm run tokens`.';

// ---------------------------------------------------------------- reading the tokens

const get = (path) => path.split('.').reduce((o, k) => o?.[k], tokens);
const resolve = (v) => {
  for (let i = 0; typeof v === 'string' && v.startsWith('{') && i < 8; i++) v = get(v.slice(1, -1)).$value;
  return v;
};
const hex = (v) => resolve(v).replace('#', '').toUpperCase();
const num = (v) => parseFloat(String(resolve(v)));
const camel = (s, upper = false) => {
  const c = s.replace(/[-_.](\w)/g, (_, x) => x.toUpperCase());
  return upper ? c[0].toUpperCase() + c.slice(1) : c;
};
const leaves = (group) => Object.entries(group).filter(([k]) => !k.startsWith('$'));

const palette = [];
for (const [family, shades] of leaves(tokens.color)) {
  if (shades.$value) palette.push([camel(family), hex(shades.$value)]);
  else for (const [shade, t] of leaves(shades)) palette.push([camel(family) + shade, hex(t.$value)]);
}
const themes = Object.fromEntries(leaves(tokens.theme).map(([name, roles]) => [name, leaves(roles).map(([role, t]) => [role, hex(t.$value)])]));
const roles = themes.dark.map(([r]) => r);
for (const [name, rs] of Object.entries(themes)) {
  if (rs.map(([r]) => r).join() !== roles.join()) throw new Error(`theme ${name} does not define the same roles as dark`);
}
const dims = (group) => leaves(tokens[group]).map(([k, t]) => [k, num(t.$value)]);
const types = leaves(tokens.type).map(([k, t]) => {
  const v = t.$value;
  return { name: k, size: num(v.fontSize), line: num(v.lineHeight), weight: v.fontWeight, tabular: (v.fontFeatures || '').includes('tnum'), tracking: v.letterSpacing ? num(v.letterSpacing) : 0 };
});
const motion = leaves(tokens.motion).filter(([, t]) => t.$type === 'duration').map(([k, t]) => [k, num(t.$value)]);

// Every icon is plain path data with explicit commands, so each platform's parser reads it
// the same way: absolute M, L, H, V, C, A and Z only, numbers separated by spaces.
const icons = Object.entries(iconSet.icons);
for (const [name, ic] of icons) {
  if (!/^[a-z]+$/.test(name) || !ic.sf || !ic.paths?.length) throw new Error(`icon ${name}: needs a lowercase name, an sf symbol and paths`);
  for (const d of ic.paths) {
    if (!/^M[-0-9. ]+(?:[LHVCAZ][-0-9. ]*)*$/.test(d)) throw new Error(`icon ${name}: path ${d} is not plain M/L/H/V/C/A/Z data`);
  }
}

// ---------------------------------------------------------------- Kotlin

const kt = () => {
  const L = [`// ${header}`, 'package br.com.gooners.pay.ui', '',
    'import androidx.compose.ui.graphics.Color', 'import androidx.compose.ui.text.TextStyle', 'import androidx.compose.ui.text.font.FontWeight',
    'import androidx.compose.ui.unit.dp', 'import androidx.compose.ui.unit.em', 'import androidx.compose.ui.unit.sp', '',
    '/** The primitive colours. Screens use the semantic roles of [SemanticColors]. */', 'object Palette {'];
  for (const [n, h] of palette) L.push(`    val ${camel(n, true)} = Color(0xFF${h})`);
  L.push('}', '', '/** One theme\'s semantic colours (docs/06 §3). */', 'data class SemanticColors(');
  for (const r of roles) L.push(`    val ${camel(r)}: Color,`);
  L.push(')', '', 'object Themes {');
  for (const [name, rs] of Object.entries(themes)) {
    L.push(`    val ${camel(name, true)} = SemanticColors(`);
    for (const [r, h] of rs) L.push(`        ${camel(r)} = Color(0xFF${h}),`);
    L.push('    )');
  }
  L.push('}', '');
  for (const [group, obj] of [['space', 'Space'], ['radius', 'Radius'], ['size', 'Sizes']]) {
    L.push(`object ${obj} {`);
    for (const [k, v] of dims(group)) L.push(`    val ${camel(k, true)} = ${v}.dp`);
    L.push('}', '');
  }
  L.push('/** The type scale. The apps use the platform font; amounts take tabular figures. */', 'object TypeScale {');
  for (const t of types) {
    const extra = (t.tabular ? ', fontFeatureSettings = "tnum"' : '') + (t.tracking ? `, letterSpacing = ${t.tracking}.em` : '');
    L.push(`    val ${camel(t.name, true)} = TextStyle(fontSize = ${t.size}.sp, lineHeight = ${t.line}.sp, fontWeight = FontWeight(${t.weight})${extra})`);
  }
  L.push('}', '', 'object Motion {');
  for (const [k, v] of motion) L.push(`    const val ${camel(k, true)}Millis = ${v}`);
  L.push('}', '');
  return L.join('\n');
};

// ---------------------------------------------------------------- Swift

const swiftWeight = { 400: '.regular', 500: '.medium', 600: '.semibold', 700: '.bold', 800: '.heavy' };
const swift = () => {
  const L = [`// ${header}`, 'import SwiftUI', '', '/// The primitive colours, as 0xRRGGBB. Screens use the semantic roles of `SemanticPalette`.', 'enum Palette {'];
  for (const [n, h] of palette) L.push(`    static let ${camel(n)}: UInt32 = 0x${h}`);
  L.push('}', '', '/// One theme\'s semantic colours (docs/06 §3), as 0xRRGGBB.', 'struct SemanticPalette {');
  for (const r of roles) L.push(`    let ${camel(r)}: UInt32`);
  L.push('}', '', 'enum Themes {');
  for (const [name, rs] of Object.entries(themes)) {
    L.push(`    static let ${camel(name)} = SemanticPalette(`);
    L.push(rs.map(([r, h]) => `        ${camel(r)}: 0x${h}`).join(',\n'));
    L.push('    )');
  }
  L.push('}', '');
  for (const [group, obj] of [['space', 'Space'], ['radius', 'Radius'], ['size', 'Sizes']]) {
    L.push(`enum ${obj} {`);
    for (const [k, v] of dims(group)) L.push(`    static let ${camel(k)}: CGFloat = ${v}`);
    L.push('}', '');
  }
  L.push('/// A text style of the type scale: points, weight, tabular figures and tracking.', 'struct TypeStyle {',
    '    let size: CGFloat', '    let lineHeight: CGFloat', '    let weight: Font.Weight', '    let tabular: Bool', '    let tracking: CGFloat', '}', '', 'enum TypeScale {');
  for (const t of types) {
    L.push(`    static let ${camel(t.name)} = TypeStyle(size: ${t.size}, lineHeight: ${t.line}, weight: ${swiftWeight[t.weight]}, tabular: ${t.tabular}, tracking: ${t.tracking})`);
  }
  L.push('}', '', 'enum Motion {');
  for (const [k, v] of motion) L.push(`    static let ${camel(k)}: Double = ${v / 1000}`);
  L.push('}', '');
  return L.join('\n');
};

// ---------------------------------------------------------------- CSS

const css = () => {
  const vars = (name) => themes[name].map(([r, h]) => `  --${r}: #${h};`).join('\n');
  const statics = [
    ...dims('space').map(([k, v]) => `  --space-${k}: ${v}px;`),
    ...dims('radius').map(([k, v]) => `  --radius-${k}: ${v}px;`),
    ...dims('size').map(([k, v]) => `  --size-${k}: ${v}px;`),
    ...motion.map(([k, v]) => `  --motion-${k}: ${v}ms;`),
  ].join('\n');
  const typeClasses = types.map((t) =>
    `.t-${t.name} { font-size: ${t.size}px; line-height: ${t.line}px; font-weight: ${t.weight};${t.tabular ? ' font-variant-numeric: tabular-nums;' : ''}${t.tracking ? ` letter-spacing: ${t.tracking}em;` : ''} }`).join('\n');
  return `/* ${header} */
/* Dark is the console's default; light follows the system or the toggle; sunlight is chosen. */
:root {
${vars('dark')}
${statics}
  color-scheme: dark;
}
:root[data-theme="light"] {
${vars('light')}
  color-scheme: light;
}
@media (prefers-color-scheme: light) {
  :root:not([data-theme="dark"]):not([data-theme="sunlight"]) {
${vars('light').replace(/^ {2}/gm, '    ')}
    color-scheme: light;
  }
}
:root[data-theme="sunlight"] {
${vars('sunlight')}
  color-scheme: light;
}
${typeClasses}
`;
};

// ---------------------------------------------------------------- icons

const ktIcons = () => {
  const L = [`// ${iconHeader}`, 'package br.com.gooners.pay.ui', '',
    'import androidx.compose.ui.graphics.Color', 'import androidx.compose.ui.graphics.SolidColor', 'import androidx.compose.ui.graphics.StrokeCap',
    'import androidx.compose.ui.graphics.StrokeJoin', 'import androidx.compose.ui.graphics.vector.ImageVector', 'import androidx.compose.ui.graphics.vector.addPathNodes',
    'import androidx.compose.ui.unit.dp', '',
    '/** The app\'s line icons; `Icon` tints them with the current content colour. */', 'object AppIcons {'];
  for (const [name, ic] of icons) L.push(`    val ${camel(name, true)}: ImageVector by lazy { icon("${name}", ${ic.paths.map((d) => JSON.stringify(d)).join(', ')}) }`);
  L.push('}', '', 'private fun icon(name: String, vararg paths: String): ImageVector =',
    `    ImageVector.Builder(name, ${iconSet.grid}.dp, ${iconSet.grid}.dp, ${iconSet.grid}f, ${iconSet.grid}f).apply {`,
    `        for (d in paths) addPath(addPathNodes(d), stroke = SolidColor(Color.Black), strokeLineWidth = ${iconSet.stroke}f, strokeLineCap = StrokeCap.Round, strokeLineJoin = StrokeJoin.Round)`,
    '    }.build()', '');
  return L.join('\n');
};

const swiftIcons = () => {
  const L = [`// ${iconHeader}`, '', '/// The SF Symbol for each of the platform\'s icons, so the iPhone app names the same things the same way.', 'enum AppIcon {'];
  for (const [name, ic] of icons) L.push(`    static let ${name} = "${ic.sf}"`);
  L.push('}', '');
  return L.join('\n');
};

const jsIcons = () => {
  const L = [`// ${iconHeader}`, `export const GRID = ${iconSet.grid};`, `export const STROKE = ${iconSet.stroke};`, '', 'export const PATHS = {'];
  for (const [name, ic] of icons) L.push(`  ${name}: [${ic.paths.map((d) => `'${d}'`).join(', ')}],`);
  L.push('};', '');
  return L.join('\n');
};

// ---------------------------------------------------------------- writing

const outputs = [
  [join(root, 'mobile', 'android', 'app', 'src', 'main', 'kotlin', 'br', 'com', 'gooners', 'pay', 'ui', 'DesignTokens.kt'), kt()],
  [join(root, 'mobile', 'ios', 'App', 'GoonersPay', 'Views', 'DesignTokens.swift'), swift()],
  [join(root, 'platform', 'internal', 'console', 'static', 'tokens.css'), css()],
  [join(root, 'mobile', 'android', 'app', 'src', 'main', 'kotlin', 'br', 'com', 'gooners', 'pay', 'ui', 'AppIcons.kt'), ktIcons()],
  [join(root, 'mobile', 'ios', 'App', 'GoonersPay', 'Views', 'AppIcons.swift'), swiftIcons()],
  [join(root, 'platform', 'internal', 'console', 'static', 'icon-paths.js'), jsIcons()],
];
const check = process.argv.includes('--check');
let stale = 0;
for (const [path, content] of outputs) {
  const cur = existsSync(path) ? readFileSync(path, 'utf8') : '';
  if (cur === content) continue;
  if (check) {
    console.error(`stale: ${path.slice(root.length + 1)} (run npm run tokens)`);
    stale++;
  } else {
    writeFileSync(path, content);
    console.log(`wrote ${path.slice(root.length + 1)}`);
  }
}
if (check && stale) process.exit(1);
